import cmath

def solve_quadratic(a, b, c):
    """
    Solves a quadratic equation of the form ax^2 + bx + c = 0.

    Args:
        a (float): Coefficient of x^2.
        b (float): Coefficient of x.
        c (float): Constant term.

    Returns:
        tuple: A tuple containing the solutions (roots) of the quadratic equation.
               If 'a' is 0, it returns a message indicating it's not a quadratic equation.
               If there are two distinct real roots, it returns (x1, x2).
               If there is one real root (repeated), it returns (x1,).
               If there are two complex roots, it returns (x1, x2).
    """
    if a == 0:
        if b == 0:
            if c == 0:
                return "Infinite solutions (0 = 0)"
            else:
                return "No solution (e.g., 5 = 0)"
        else:
            # Linear equation: bx + c = 0
            x = -c / b
            return (x,)

    delta = (b**2) - 4*(a*c)

    if delta > 0:
        # Two distinct real roots
        x1 = (-b - delta**0.5) / (2*a)
        x2 = (-b + delta**0.5) / (2*a)
        return (x1, x2)
    elif delta == 0:
        # One real root (repeated)
        x = -b / (2*a)
        return (x,)
    else:
        # Two complex roots
        x1 = (-b - cmath.sqrt(delta)) / (2*a)
        x2 = (-b + cmath.sqrt(delta)) / (2*a)
        return (x1, x2)

if __name__ == "__main__":
    print("Quadratic Equation Solver (ax^2 + bx + c = 0)")

    while True:
        try:
            a = float(input("Enter coefficient 'a': "))
            b = float(input("Enter coefficient 'b': "))
            c = float(input("Enter coefficient 'c': "))
            break
        except ValueError:
            print("Invalid input. Please enter numerical values for coefficients.")

    solutions = solve_quadratic(a, b, c)

    if isinstance(solutions, str):
        print(solutions)
    elif len(solutions) == 1:
        print(f"One real root: x = {solutions[0]}")
    else:
        print(f"Two roots: x1 = {solutions[0]}, x2 = {solutions[1]}")

    # Example usage with different scenarios:
    print("\n--- Example Scenarios ---")
    print("Equation: x^2 - 5x + 6 = 0")
    print(f"Solutions: {solve_quadratic(1, -5, 6)}") # Expected: (2.0, 3.0)

    print("Equation: x^2 + 4x + 4 = 0")
    print(f"Solutions: {solve_quadratic(1, 4, 4)}")   # Expected: (-2.0,)

    print("Equation: x^2 + 2x + 5 = 0")
    print(f"Solutions: {solve_quadratic(1, 2, 5)}")
